mapper.select:
    	SELECT
			T1.EFF_DATE,
			T1.BASIS,
			T1.YIELD
		FROM
			FIN_CASH_CALC_RULE T1
			LEFT JOIN FIN_CASH_INFO T2 ON T2.FINPROD_ID = #{finprodId,jdbcType=VARCHAR}
			AND T2.FINPROD_TYPE = #{finprodType,jdbcType=VARCHAR}
			AND T2.CASH_TYPE_2 = #{cashType,jdbcType=VARCHAR}
			AND T2.CASH_ID = T1.CASH_ID
			where T1.FINPROD_ID= #{finprodId,jdbcType=VARCHAR}
			AND T1.IS_INITIAL = #{isInitial,jdbcType=VARCHAR}

SELECT T3.FINPROD_ID, T3.FINPROD_TYPE, T3.FINPROD_TYPE2, T3.FINPROD_MARKET_ID, T3.FINPROD_NAME, T3.FINPROD_ABBR, T3.ISSUE_AMT, T3.VDATE, T1.EFF_DATE, T1.CALC_TYPE, T1.BASE_TYPE, T1.BASE_DATE_TYPE, T1.BASIS, T1.YIELD*100 YIELD, T1.IS_INITIAL, T1.BRANCH, T2.CASH_ID, T2.FEE_ID FROM FIN_CASH_CALC_RULE T1 INNER JOIN FIN_CASH_INFO T2 ON T2.CASH_ID = T1.CASH_ID LEFT JOIN FIN_PRODUCT T3 ON T3.FINPROD_ID = T1.FINPROD_ID AND T2.FINPROD_ID = T3.FINPROD_ID
AND T2.FINPROD_TYPE = #{finprodType,jdbcType=VARCHAR}
and T2.CASH_TYPE_2 in ('C11','C12','C13')
AND T2.CASH_TYPE_1 = #{cashType1,jdbcType=VARCHAR}
AND T2.CASH_TYPE_2 = #{cashType2,jdbcType=VARCHAR}
AND T3.FINPROD_ID = #{finprodId,jdbcType=VARCHAR}
order by T1.EFF_DATE ASC

SELECT T3.FINPROD_ID, T3.FINPROD_TYPE, T3.FINPROD_TYPE2, T3.FINPROD_MARKET_ID, T3.FINPROD_NAME, T3.FINPROD_ABBR, T3.ISSUE_AMT, T3.VDATE, T1.EFF_DATE, T1.CALC_TYPE, T1.BASE_TYPE, T1.BASE_DATE_TYPE, T1.BASIS, T1.YIELD*100 YIELD, T1.IS_INITIAL, T1.BRANCH, T2.CASH_ID, T2.FEE_ID FROM FIN_CASH_CALC_RULE T1 LEFT JOIN FIN_PRODUCT T3 ON T3.FINPROD_ID = T1.FINPROD_ID INNER JOIN FIN_CASH_INFO T2 ON T2.CASH_ID = T1.CASH_ID AND T2.FINPROD_ID = T3.FINPROD_ID
AND T2.FINPROD_TYPE = #{finprodType,jdbcType=VARCHAR}
AND T2.CASH_TYPE_1 = #{cashType1,jdbcType=VARCHAR}
AND T2.CASH_TYPE_2 = #{cashType2,jdbcType=VARCHAR}
AND T1.FINPROD_ID = #{finprodId,jdbcType=VARCHAR}
order by T1.EFF_DATE ASC

SELECT T1.COUPON_SPECIES, T3.INT_TYPE FROM FIN_PRODUCT T1 LEFT JOIN FIN_CASH_INFO T2 ON T2.FINPROD_ID = T1.FINPROD_ID
AND T2.CASH_TYPE_2 = #{cashType,jdbcType=VARCHAR}
LEFT JOIN FIN_RATE_INFO T3 ON T3.CASH_ID = T2.CASH_ID AND T3.EFF_DATE = T1.VDATE
AND T1.FINPROD_ID = #{finprodId,jdbcType=VARCHAR}

SELECT T1.CASH_ID CASH_ID, T1.MDATE MDATE, T1.CASH_NUM CASH_NUM, T1.CASH_TYPE CASH_TYPE, T1.VDATE_UNADJUST VDATE_UNADJUST, T1.MDATE_UNADJUST MDATE_UNADJUST, T1.PAY_DATE_UNADJUST PAY_DATE_UNADJUST, T1.VDATE VDATE, T1.PAY_DATE PAY_DATE, T1.TERMDAYS TERMDAYS, T1.VDATE_Y VDATE_Y, T1.VDATE_TERM VDATE_TERM, T1.MDATE_TERM MDATE_TERM, T1.TERMDAYS_TERM TERMDAYS_TERM, T1.PRIN_AMT PRIN_AMT, T1.INT_PRIN_AMT INT_PRIN_AMT, T1.INT_AMT INT_AMT, T1.IS_PAY_INT IS_PAY_INT, T1.CASH_AMT CASH_AMT, T1.CASH_BASEAMT CASH_BASEAMT, T1.CASH_UNIT_TYPE CASH_UNIT_TYPE, T1.CALC_FUNCTION CALC_FUNCTION, T1.FREQUENCY FREQUENCY, T1.FINPROD_ID FINPROD_ID, T1.FINPROD_TYPE FINPROD_TYPE, T1.FINPROD_TYPE2 FINPROD_TYPE2, T1.BRANCH BRANCH, T1.PAY_TYPE PAY_TYPE,T1.RANGE_YIELD*100 RANGE_YIELD, T1.CREATE_USER CREATE_USER, T1.CREATE_DEPT CREATE_DEPT, T1.CREATE_TIME CREATE_TIME, T1.UPDATE_USER UPDATE_USER, T1.UPDATE_TIME UPDATE_TIME ,T2.CASH_TYPE_2 FROM FIN_CASH_PLAN T1, FIN_CASH_INFO T2 WHERE T2.CASH_ID = T1.CASH_ID
AND T2.FINPROD_ID = #{finprodId,jdbcType=VARCHAR}
AND T2.CASH_TYPE_2 = #{cashType,jdbcType=VARCHAR}
AND T2.FINPROD_TYPE = #{finprodType,jdbcType=VARCHAR}
ORDER BY T1.VDATE ASC

SELECT T1.CASH_ID CASH_ID, T1.CASH_TYPE_1 CASH_TYPE_1, T1.CASH_TYPE_2 CASH_TYPE_2, T1.CCY CCY, T1.FINPROD_ID FINPROD_ID, T1.FINPROD_TYPE FINPROD_TYPE, T1.BRANCH BRANCH, T1.FEE_ID FEE_ID, T1.CHL_FINPROD_ID CHL_FINPROD_ID, T1.CHL_LEVEL CHL_LEVEL, T1.CREATE_USER CREATE_USER, T1.CREATE_DEPT CREATE_DEPT, T1.CREATE_TIME CREATE_TIME, T1.UPDATE_USER UPDATE_USER, T1.UPDATE_TIME UPDATE_TIME ,T2.FINPROD_ID FINPROD_ID , T2.FINPROD_TYPE FINPROD_TYPE , T2.FINPROD_TYPE2 FINPROD_TYPE2 , T2.FINPROD_ABBR FINPROD_ABBR , T2.FINPROD_NAME FINPROD_NAME , T2.COUPON_SPECIES , T3.EFF_DATE EFF_DATE , T3.PAY_CYCLE_VAL PAY_CYCLE_VAL , T3.PAY_CYCLE PAY_CYCLE , T3.DAY_TYPE DAY_TYPE , T3.DAY_VALUE DAY_VALUE , T3.END_TDAY_RULE END_TDAY_RULE , T3.PAY_TDAY_RULE PAY_TDAY_RULE , T3.CALC_RULE CALC_RULE , T3.FIRST_PAY_DATE FIRST_PAY_DATE , T3.CASH_UNIT_TYPE CASH_UNIT_TYPE ,T3.REMARK REMARK FROM FIN_CASH_INFO T1 LEFT JOIN FIN_PRODUCT T2 ON T2.FINPROD_ID = T1.FINPROD_ID LEFT JOIN FIN_CASH_PAY_RULE T3 ON T3.CASH_ID = T1.CASH_ID
AND T3.EFF_DATE = to_date ( #{vdate}, 'yyyy-mm-dd' )
AND T1.FINPROD_ID = #{finprodId,jdbcType=VARCHAR}
AND T1.CASH_TYPE_2 = #{cashType,jdbcType=VARCHAR}
AND T1.FINPROD_TYPE = #{finprodType,jdbcType=VARCHAR}
